function kernelGuide(){
 const wasOpen=$('kernel-guide').querySelector('details')?.open||false,target=$('kernel-guide'),circuit=valueOf('build-regime')==='circuit',joint=valueOf('build-family')==='bp4',ms=valueOf('build-rule')==='min_sum';target.replaceChildren();
 const detail=el('details');detail.open=wasOpen;detail.append(el('summary',{},circuit?'Circuit BP kernel':joint?'Q-BP kernel and numerical rules':'BP kernel and numerical rules'));
 detail.append(el('p',{class:'small'},'Flooding: complete all checks from the old V2C buffer, then update variables from the original prior. A correction is tested after each completed sweep.'));
 equation(detail,ms?String.raw`\hat m_{c\to v}^{(t+1)}=(-1)^{s_c}\!\prod_{u\in\partial c\setminus v}\!\operatorname{sgn}(m_{u\to c}^{(t)})\;\alpha\max\!\left(0,\min_{u\in\partial c\setminus v}|m_{u\to c}^{(t)}|-\beta\right)` :String.raw`\hat m_{c\to v}^{(t+1)}=2\operatorname{atanh}\!\left[(-1)^{s_c}\!\prod_{u\in\partial c\setminus v}\tanh\!\left(\frac{m_{u\to c}^{(t)}}{2}\right)\right]`);
 if(!circuit&&joint){
  equation(detail,String.raw`m_v^a=\log\frac{P_v(I)}{P_v(a)}+\sum_{c\in\partial v}A_{cv}(a)\hat m_{c\to v},\qquad a\in\{X,Y,Z\}`);
  equation(detail,String.raw`m_{v\to c}=\log\frac{\sum_{P:[P,g_{cv}]=0}\exp B_{v\to c}(P)}{\sum_{P:\{P,g_{cv}\}=0}\exp B_{v\to c}(P)}`);
  detail.append(el('p',{class:'small'},'A is 1 for anticommuting Paulis. Exclude the destination check before projection. Three identity-referenced LLRs retain a four-Pauli belief; check messages are scalar. Encoding and prior order: I, X, Y, Z. Strict Pauli decisions test I, then X, then Z using strict comparisons, otherwise choose Y.'));
 }else{
  equation(detail,String.raw`m_v=\lambda_v+\sum_{c\in\partial v}\hat m_{c\to v},\qquad m_{v\to c}=m_v-\hat m_{c\to v},\qquad\lambda_v=\log\frac{1-q_v}{q_v}`);
  detail.append(el('p',{class:'small'},circuit?'q is the independent mechanism probability from the detector error model. Corrections predict logical observables from sampled detectors.':'Separate X/Z component graphs; depolarizing priors use component probability 2p₀/3, while the physical channel remains X, Y, Z each p/3. A negative LLR selects 1; ties select 0.'));
 }
 if(!circuit){equation(detail,String.raw`m\leftarrow d\,m_{\mathrm{old}}+(1-d)\,m_{\mathrm{new}}`);detail.append(el('p',{class:'small'},`V2C damping: d = ${valueOf('build-damping')}. ${joint?'It acts on the three extrinsic state LLRs before their scalar edge projection.':'It acts on scalar extrinsic messages.'} Guided decimation, when enabled, keeps the message state between rounds and changes only the fixed prior.`));}
 detail.append(el('p',{class:'small'},circuit?'Pinned circuit float64 profiles preserve symmetric ±25 message saturation for SPA and MS. Their identity is separate from the v2 code-capacity profiles.':valueOf('build-version')==='v1'?'Historical v1 uses global symmetric ±25 clipping. It is retained only for explicit historical specifications.':'v2 float64: no global prior, belief, or V2C clipping. For SPA, m/2 beyond ±20 saturates tanh; a product reaching ±1 becomes ±(1−10⁻¹⁰), giving a check message of about ±23.719. Invalid numerical states raise errors.'));
 if(!circuit&&valueOf('build-format').startsWith('int'))detail.append(el('p',{class:'small'},`Selected resolution: ${valueOf('build-format')}, step 1/${valueOf('build-scale')}, scope ${valueOf('build-scope')}, coefficients ${valueOf('build-coefficients')}. Rounding is nearest-even with symmetric saturation. The exact policy is included in the JSON.`));
 target.append(detail);
}
